function bytes(b64){const bin=atob(b64);const out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out;}
export default { async fetch(request) { const url=new URL(request.url); let key=url.pathname; if(key.endsWith('/')) key='/'; const asset=ASSETS[key] || ASSETS[decodeURIComponent(key)] || ASSETS['/']; const headers={'content-type': asset.type, 'cache-control': 'public, max-age=0, must-revalidate'}; return new Response(bytes(asset.body), {headers}); } };
